-- Safe additive role presets. Existing accounts retain their access until explicitly changed.
ALTER TABLE legalflow.users ADD COLUMN IF NOT EXISTS role_profile text;
CREATE TABLE IF NOT EXISTS legalflow.role_profiles (id text PRIMARY KEY,base_role text NOT NULL CHECK(base_role IN ('owner','manager','staff')),permissions jsonb NOT NULL DEFAULT '{}'::jsonb,updated_at timestamptz NOT NULL DEFAULT now());
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='users_role_profile_fkey' AND conrelid='legalflow.users'::regclass) THEN ALTER TABLE legalflow.users ADD CONSTRAINT users_role_profile_fkey FOREIGN KEY(role_profile) REFERENCES legalflow.role_profiles(id); END IF; END $$;

UPDATE legalflow.role_permissions SET permissions=jsonb_build_object('cases.view',true,'cases.details',true,'cases.financials',true,'cases.import',true,'files.view',true,'files.legal',true,'files.upload',true,'files.edit',true,'files.delete',true,'files.approve',role='manager','reports.export',true,'email.use',true,'chat.use',true,'calendar.manage',true,'team.assign',role='manager') || permissions WHERE role IN ('staff','manager');
